import{_ as t,H as n,f as a,i as s}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"复习课（四） | 任务管理","description":"","frontmatter":{},"headers":[{"level":3,"title":"（四）任务管理","slug":"四-任务管理","link":"#四-任务管理","children":[]}],"relativePath":"技术管理实战36讲/复习课（四）-任务管理.md","filePath":"技术管理实战36讲/复习课（四）-任务管理.md","lastUpdated":1779820334000}'),r={name:"技术管理实战36讲/复习课（四）-任务管理.md"};function o(i,e,g,E,p,h){return n(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="复习课-四-任务管理" tabindex="-1">复习课（四） | 任务管理 <a class="header-anchor" href="#复习课-四-任务管理" aria-label="Permalink to &quot;复习课（四） | 任务管理&quot;">​</a></h1><hr><p>继上一篇的“ <strong>团队建设</strong>”之后，接下来我们继续来复习“管理方法论”的另外一个方面： <strong>任务管理</strong>。</p><h3 id="四-任务管理" tabindex="-1">（四）任务管理 <a class="header-anchor" href="#四-任务管理" aria-label="Permalink to &quot;（四）任务管理&quot;">​</a></h3><p>任务管理——“做事”这个话题很大，要如何探讨呢？既然做事是一个过程，那么就可以将其分成“ <strong>事前</strong>”“ <strong>事中</strong>”和“ <strong>事后</strong>”三段来探讨。</p><p><strong>事前</strong>，需要提前想清楚：要做哪些事？先做哪件，后做哪件？也就是 <strong>分清楚轻重缓急</strong>，也叫优先级梳理。</p><p><strong>事中</strong>，要确保事情是按照计划推进的，即 <strong>有效地推进执行</strong>。</p><p><strong>事后</strong>，要复盘做事的整个过程，并从中抽取一些 <strong>流程机制</strong>，以便以后在类似的场景下也可以做得更好、更顺畅。</p><p>这样就抽出了任务管理三要素：事前的 <strong>轻重缓急</strong>、事中的 <strong>有效执行</strong> 和事后的 <strong>流程机制</strong>。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68509/2ae92847af34409a489198a7a1a6911e.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68509/2ae92847af34409a489198a7a1a6911e.png" alt=""></a></p><p>“做事”：任务管理三要素</p><p><strong>1. 轻重缓急</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68509/8c4e83aac51060f3931f487a957443a3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68509/8c4e83aac51060f3931f487a957443a3.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/41448" target="_blank" rel="noreferrer">第25篇《多任务并行该如何应对？》</a></p><p><strong>2. 有效执行</strong></p><p>项目有效执行过程中常见的四大类问题，作者将其总结出一份 <strong>检查清单</strong>，我印象极其深刻，因为有了它，我就可以全面剖析“做事ing”这个过程，进行“自查”，找“病因”，开“药方”了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68509/8a6ec8ff2d0a9efb23b5585a5ef1536f.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68509/8a6ec8ff2d0a9efb23b5585a5ef1536f.png" alt=""></a></p><p>任务执行检查清单</p><p>这也就引出了：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68509/286d2283ada78becfad784f42c565e9b.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68509/286d2283ada78becfad784f42c565e9b.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/41653" target="_blank" rel="noreferrer">第26篇《如何确保项目的有效执行？》</a></p><p><strong>3. 流程机制</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68509/49011f37c22b4657375882b36381d9f1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/68509/49011f37c22b4657375882b36381d9f1.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/41830" target="_blank" rel="noreferrer">第27篇《如何让流程机制得到有效的执行？》</a></p><p>至此我们就复习完了任务管理三要素：事前的 <strong>轻重缓急</strong>、事中的 <strong>有效执行</strong> 和事后的 <strong>流程机制</strong>。详细内容也可戳文中所附的链接。</p><hr>',26)])])}const A=t(r,[["render",o]]);export{c as __pageData,A as default};
